12	func newTestNodeCap(t *testing.T, keys []testKey, maxTxs, capacity uint64) (*Node, string) {
13		t.Helper()
14		dir := t.TempDir()
15		vals := make([][]byte, len(keys))
16		for i, k := range keys {
17			vals[i] = k.pub
18		}
19		n, err := New(dir, Config{Seed: []byte("test-seed-cap"), Validators: vals, MaxTxsPerBlock: maxTxs, PoolCapacity: capacity})
20		if err != nil {
21			t.Fatal(err)
22		}
23		return n, dir
24	}
