55	// 满池时费用不更高的新交易被 pool-full 拒绝：池不变、不留历史、腾出位置后可重新提交。
56	// 费用更高时挤出费用最低者，结果给出被挤出标识，旧交易保留完整内容并显示 dropped。
57	func TestCapacityEviction(t *testing.T) {
58		keys := genKeys(t, 4)
59		n, _ := newTestNodeCap(t, keys, 10, 2)
60	
61		a := NewTransaction(keys[0].priv, 1, []byte("a"), 5, 100)
62		b := NewTransaction(keys[1].priv, 1, []byte("b"), 3, 100)
63		for _, tx := range []*Transaction{a, b} {
64			if _, err := n.Submit(tx); err != nil {
65				t.Fatal(err)
66			}
67		}
68	
69		// 费用低于池中最低：拒绝，池保持不变，且不留任何历史。
70		cheap := NewTransaction(keys[2].priv, 1, []byte("cheap"), 2, 100)
71		if _, err := n.Submit(cheap); reason(err) != ReasonPoolFull {
72			t.Fatalf("cheap tx got %v, want %s", err, ReasonPoolFull)
73		}
74		if _, err := n.Tx(cheap.ID()); reason(err) != ReasonUnknownTx {
75			t.Fatalf("rejected tx left history: %v", err)
76		}
77		if info, _ := n.Tx(a.ID()); info.Status != StatusQueued {
78			t.Fatalf("rejected submit changed pool: a = %s", info.Status)
79		}
80		if info, _ := n.Tx(b.ID()); info.Status != StatusQueued {
81			t.Fatalf("rejected submit changed pool: b = %s", info.Status)
82		}
83	
84		// 费用更高：挤出费用最低的 b。
85		d := NewTransaction(keys[2].priv, 1, []byte("d"), 4, 100)
86		res, err := n.Submit(d)
87		if err != nil {
88			t.Fatal(err)
89		}
90		if res.EvictedID != b.ID() || res.TxID != d.ID() || res.ReplacedID != "" {
91			t.Fatalf("eviction result wrong: %+v", res)
92		}
93	
94		// 被挤出的交易保留完整内容，显示 dropped/pool-capacity/发生轮次，
95		// 不带确认块或替换交易关联。
96		info, err := n.Tx(b.ID())
97		if err != nil {
98			t.Fatal(err)
99		}
100		if info.Status != StatusDropped || info.DropReason != DropReasonPoolCapacity || info.DropRound != 1 {
101			t.Fatalf("dropped tx wrong: %+v", info)
102		}
103		if info.BlockHeight != 0 || info.BlockID != "" || info.ReplacedBy != "" {
104			t.Fatalf("dropped tx must not carry block/replace links: %+v", info)
105		}
106		if info.Tx == nil || string(info.Tx.Content) != "b" || info.Tx.Fee != 3 {
107			t.Fatalf("dropped tx content not preserved: %+v", info.Tx)
108		}
109		// 不再占用位置：账户待处理列表为空。
110		if acct := n.Account(keys[1].pub); len(acct.Pending) != 0 {
111			t.Fatalf("dropped tx still pending: %+v", acct)
112		}
113	
114		// 再次提交完全相同的旧交易仍按重复拒绝。
115		if _, err := n.Submit(NewTransaction(keys[1].priv, 1, []byte("b"), 3, 100)); reason(err) != ReasonDuplicate {
116			t.Fatalf("resubmit dropped tx got %v, want %s", err, ReasonDuplicate)
117		}
118	
119		// 同发送者同序号的新交易按普通提交规则竞争位置：费用足够高即可挤出别人。
120		b2 := NewTransaction(keys[1].priv, 1, []byte("b2"), 10, 100)
121		res, err = n.Submit(b2)
122		if err != nil {
123			t.Fatal(err)
124		}
125		if res.EvictedID != d.ID() || res.ReplacedID != "" {
126			t.Fatalf("fresh same-seq tx should compete normally: %+v", res)
127		}
128	
129		// 被挤出的交易不能再用于登记候选。
130		if _, err := n.Propose(); err != nil {
131			t.Fatal(err)
132		}
133		if _, err := n.RegisterCandidate(1, []string{d.ID()}); reason(err) != ReasonTxNotInPool {
134			t.Fatalf("dropped tx in candidate got %v, want %s", err, ReasonTxNotInPool)
135		}
136	}
