138	// 同费时淘汰标识字典序最大者；新交易费用相同且标识更小时才能挤出，否则 pool-full。
139	func TestCapacityEvictionTieBreak(t *testing.T) {
140		keys := genKeys(t, 4)
141		n, _ := newTestNodeCap(t, keys, 10, 2)
142	
143		a := NewTransaction(keys[0].priv, 1, []byte("a"), 5, 100)
144		b := NewTransaction(keys[1].priv, 1, []byte("b"), 5, 100)
145		n.Submit(a)
146		n.Submit(b)
147		victim := a.ID()
148		if b.ID() > victim {
149			victim = b.ID()
150		}
151	
152		// 构造两笔同费交易：一笔标识小于淘汰对象（可挤出），一笔大于（被拒绝）。
153		var smaller, larger *Transaction
154		for i := 0; smaller == nil || larger == nil; i++ {
155			tx := NewTransaction(keys[2].priv, uint64(i+1), []byte(fmt.Sprintf("c%d", i)), 5, 100)
156			if tx.ID() < victim && smaller == nil {
157				smaller = tx
158			}
159			if tx.ID() > victim && larger == nil {
160				larger = tx
161			}
162		}
163	
164		res, err := n.Submit(smaller)
165		if err != nil {
166			t.Fatalf("same-fee smaller-id tx should evict: %v", err)
167		}
168		if res.EvictedID != victim {
169			t.Fatalf("evicted %s, want lexicographically largest %s", res.EvictedID, victim)
170		}
171	
172		// 池中现为幸存者与新交易（同费）：同费但标识更大的交易不能挤出。
173		curVictim := a.ID()
174		if curVictim == victim {
175			curVictim = b.ID()
176		}
177		if smaller.ID() > curVictim {
178			curVictim = smaller.ID()
179		}
180		if larger.ID() < curVictim {
181			t.Fatal("test setup: larger tx id must exceed current victim")
182		}
183		if _, err := n.Submit(larger); reason(err) != ReasonPoolFull {
184			t.Fatalf("same-fee larger-id tx got %v, want %s", err, ReasonPoolFull)
185		}
186		if _, err := n.Tx(larger.ID()); reason(err) != ReasonUnknownTx {
187			t.Fatalf("rejected tx left history: %v", err)
188		}
189	}
