191	// 满池时合法的加费替换不增加计数、可执行且不淘汰其他交易；被未决候选引用的交易仍禁止替换。
192	func TestCapacityReplacementWhenFull(t *testing.T) {
193		keys := genKeys(t, 4)
194		n, _ := newTestNodeCap(t, keys, 10, 1)
195	
196		a := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
197		if _, err := n.Submit(a); err != nil {
198			t.Fatal(err)
199		}
200		// 满池替换：不淘汰任何交易。
201		ahi := NewTransaction(keys[0].priv, 1, []byte("ahi"), 2, 100)
202		res, err := n.Submit(ahi)
203		if err != nil {
204			t.Fatalf("replacement on full pool must succeed: %v", err)
205		}
206		if res.ReplacedID != a.ID() || res.EvictedID != "" {
207			t.Fatalf("replacement must not evict: %+v", res)
208		}
209		// 计数不变：池仍满，新交易仍需竞争。
210		b := NewTransaction(keys[1].priv, 1, []byte("b"), 1, 100)
211		if _, err := n.Submit(b); reason(err) != ReasonPoolFull {
212			t.Fatalf("got %v, want %s", err, ReasonPoolFull)
213		}
214	
215		// 被未决候选引用的交易仍禁止替换。
216		p, err := n.Propose()
217		if err != nil {
218			t.Fatal(err)
219		}
220		if len(p.TxIDs) != 1 || p.TxIDs[0] != ahi.ID() {
221			t.Fatalf("proposal = %v, want [ahi]", p.TxIDs)
222		}
223		locked := NewTransaction(keys[0].priv, 1, []byte("locked"), 99, 100)
224		if _, err := n.Submit(locked); reason(err) != ReasonProposalLocked {
225			t.Fatalf("replacing proposed tx got %v, want %s", err, ReasonProposalLocked)
226		}
227	}
