229	// 被未决候选引用的交易受保护：占位但不可淘汰；轮次结束后只解除保护、仍占位置。
230	func TestCapacityProtection(t *testing.T) {
231		keys := genKeys(t, 4)
232		n, _ := newTestNodeCap(t, keys, 10, 1)
233	
234		a := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
235		n.Submit(a)
236		if _, err := n.Propose(); err != nil { // a 进入本地提议，受保护
237			t.Fatal(err)
238		}
239	
240		// 池中唯一交易受保护：任何费用的全新交易都无可淘汰者。
241		b := NewTransaction(keys[1].priv, 1, []byte("b"), 1000, 100)
242		if _, err := n.Submit(b); reason(err) != ReasonPoolFull {
243			t.Fatalf("got %v, want %s", err, ReasonPoolFull)
244		}
245	
246		// 主动结束轮次：a 回到排队（未到期，仍占位置），保护解除。
247		if _, err := n.EndRound(); err != nil {
248			t.Fatal(err)
249		}
250		if info, _ := n.Tx(a.ID()); info.Status != StatusQueued {
251			t.Fatalf("a after EndRound = %s, want queued", info.Status)
252		}
253		res, err := n.Submit(b)
254		if err != nil {
255			t.Fatalf("unprotected tx should be evictable: %v", err)
256		}
257		if res.EvictedID != a.ID() {
258			t.Fatalf("evicted %s, want %s", res.EvictedID, a.ID())
259		}
260		if info, _ := n.Tx(a.ID()); info.Status != StatusDropped || info.DropRound != 2 {
261			t.Fatalf("a should be dropped in round 2: %+v", info)
262		}
263	}
