341	// 淘汰不推进已确认序号；留下缺口时账户查询指出最早缺口，后续序号保留但不能越过缺口打包。
342	func TestCapacityEvictionLeavesGap(t *testing.T) {
343		keys := genKeys(t, 4)
344		n, _ := newTestNodeCap(t, keys, 10, 2)
345	
346		s1 := NewTransaction(keys[0].priv, 1, []byte("s1"), 1, 100)
347		s2 := NewTransaction(keys[0].priv, 2, []byte("s2"), 2, 100)
348		n.Submit(s1)
349		n.Submit(s2)
350	
351		x := NewTransaction(keys[1].priv, 1, []byte("x"), 5, 100)
352		res, err := n.Submit(x) // 挤出费用最低的 s1，留下序号缺口
353		if err != nil || res.EvictedID != s1.ID() {
354			t.Fatalf("eviction: %+v %v", res, err)
355		}
356		acct := n.Account(keys[0].pub)
357		if acct.ConfirmedSequence != 0 || acct.Gap != 1 || len(acct.Pending) != 1 || acct.Pending[0].ID != s2.ID() {
358			t.Fatalf("account after eviction wrong: %+v", acct)
359		}
360	
361		// s2 不能越过缺口被打包。
362		p, err := n.Propose()
363		if err != nil {
364			t.Fatal(err)
365		}
366		if len(p.TxIDs) != 1 || p.TxIDs[0] != x.ID() {
367			t.Fatalf("proposal = %v, want only x (s2 blocked by gap)", p.TxIDs)
368		}
369		confirmByVotes(t, n, keys, p.BlockID)
370		acct = n.Account(keys[0].pub)
371		if acct.ConfirmedSequence != 0 || acct.Gap != 1 || len(acct.Pending) != 1 {
372			t.Fatalf("gap must survive unrelated confirmation: %+v", acct)
373		}
374	}
