376	// 接收新交易与淘汰旧交易必须一起成功：保存失败时两笔交易状态与账户查询保持操作前结果。
377	func TestCapacityEvictionAtomicity(t *testing.T) {
378		keys := genKeys(t, 4)
379		n, dir := newTestNodeCap(t, keys, 10, 1)
380	
381		a := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
382		n.Submit(a)
383		before, err := os.ReadFile(filepath.Join(dir, stateFileName))
384		if err != nil {
385			t.Fatal(err)
386		}
387	
388		n.injectSaveErr = errors.New("disk full (simulated)")
389		b := NewTransaction(keys[1].priv, 1, []byte("b"), 2, 100)
390		res, err := n.Submit(b)
391		if err == nil {
392			t.Fatal("submit must fail when save fails")
393		}
394		if res != nil {
395			t.Fatalf("result should be nil on error, got %+v", res)
396		}
397		n.injectSaveErr = nil
398	
399		// 两笔交易都保持操作前状态：a 仍排队，b 无记录。
400		if info, _ := n.Tx(a.ID()); info.Status != StatusQueued {
401			t.Fatalf("a = %s, want queued after failed eviction", info.Status)
402		}
403		if _, err := n.Tx(b.ID()); reason(err) != ReasonUnknownTx {
404			t.Fatalf("b should be unknown after failed submit: %v", err)
405		}
406		if acct := n.Account(keys[0].pub); len(acct.Pending) != 1 || acct.Pending[0].ID != a.ID() {
407			t.Fatalf("account changed despite failed save: %+v", acct)
408		}
409		after, err := os.ReadFile(filepath.Join(dir, stateFileName))
410		if err != nil {
411			t.Fatal(err)
412		}
413		if string(before) != string(after) {
414			t.Fatal("state file changed despite failed write")
415		}
416	
417		// 恢复写入后同一提交正常完成。
418		res, err = n.Submit(b)
419		if err != nil || res.EvictedID != a.ID() {
420			t.Fatalf("retry after recovery: %+v %v", res, err)
421		}
422	}
