424	// 重启后恢复容量、淘汰记录与候选保护；版本 1、2 未保存容量时按不限制处理。
425	func TestCapacityPersistence(t *testing.T) {
426		keys := genKeys(t, 4)
427		n, dir := newTestNodeCap(t, keys, 10, 2)
428	
429		a := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
430		b := NewTransaction(keys[1].priv, 1, []byte("b"), 2, 100)
431		n.Submit(a)
432		n.Submit(b)
433		c := NewTransaction(keys[2].priv, 1, []byte("c"), 3, 100)
434		res, err := n.Submit(c) // 挤出 a
435		if err != nil || res.EvictedID != a.ID() {
436			t.Fatalf("eviction: %+v %v", res, err)
437		}
438		p, _ := n.Propose() // b、c 进入提议，受保护
439	
440		n2, err := Open(dir)
441		if err != nil {
442			t.Fatal(err)
443		}
444		if got := n2.Config().PoolCapacity; got != 2 {
445			t.Fatalf("restored capacity = %d, want 2", got)
446		}
447		// 淘汰记录恢复。
448		info, err := n2.Tx(a.ID())
449		if err != nil || info.Status != StatusDropped || info.DropReason != DropReasonPoolCapacity || info.DropRound != 1 {
450			t.Fatalf("dropped record not restored: %+v %v", info, err)
451		}
452		// 候选保护恢复：仍禁止替换、仍不可淘汰。
453		locked := NewTransaction(keys[1].priv, 1, []byte("locked"), 99, 100)
454		if _, err := n2.Submit(locked); reason(err) != ReasonProposalLocked {
455			t.Fatalf("replacing protected tx after reopen got %v, want %s", err, ReasonProposalLocked)
456		}
457		d := NewTransaction(keys[3].priv, 1, []byte("d"), 1000, 100)
458		if _, err := n2.Submit(d); reason(err) != ReasonPoolFull {
459			t.Fatalf("protected pool after reopen got %v, want %s", err, ReasonPoolFull)
460		}
461		// 确认后位置释放，可正常接收。
462		confirmByVotes(t, n2, keys, p.BlockID)
463		if _, err := n2.Submit(d); err != nil {
464			t.Fatalf("slots must be freed after confirm: %v", err)
465		}
466	}
467	
468	// 版本 2 的状态文件没有容量字段：打开后按不限制处理，确认历史保持原样。
469	func TestOpenV2StateWithoutCapacity(t *testing.T) {
470		keys := genKeys(t, 4)
471		n, dir := newTestNodeCap(t, keys, 10, 7)
472		a := NewTransaction(keys[0].priv, 1, []byte("a"), 1, 100)
473		n.Submit(a)
474		p, _ := n.Propose()
475		confirmByVotes(t, n, keys, p.BlockID)
476	
477		// 改写为版本 2 并删除容量字段。
478		raw, err := os.ReadFile(filepath.Join(dir, stateFileName))
479		if err != nil {
480			t.Fatal(err)
481		}
482		var doc map[string]any
483		if err := json.Unmarshal(raw, &doc); err != nil {
484			t.Fatal(err)
485		}
486		doc["version"] = float64(2)
487		delete(doc, "pool_capacity")
488		out, err := json.MarshalIndent(doc, "", "  ")
489		if err != nil {
490			t.Fatal(err)
491		}
492		if err := os.WriteFile(filepath.Join(dir, stateFileName), out, 0o644); err != nil {
493			t.Fatal(err)
494		}
495	
496		n2, err := Open(dir)
497		if err != nil {
498			t.Fatal(err)
499		}
500		if got := n2.Config().PoolCapacity; got != 0 {
501			t.Fatalf("v2 state capacity = %d, want 0 (unlimited)", got)
502		}
503		if n2.Height() != 1 || n2.CurrentRound() != 2 {
504			t.Fatalf("history changed: height=%d round=%d", n2.Height(), n2.CurrentRound())
505		}
506		if info, _ := n2.Tx(a.ID()); info.Status != StatusConfirmed || info.BlockHeight != 1 {
507			t.Fatalf("confirmed history not preserved: %+v", info)
508		}
509		// 不限制：可连续接收多笔交易。
510		for i := 0; i < 10; i++ {
511			tx := NewTransaction(keys[1].priv, uint64(i+1), []byte(fmt.Sprintf("t%d", i)), 1, 1000)
512			if _, err := n2.Submit(tx); err != nil {
513				t.Fatalf("v2 state should be unlimited: %v", err)
514			}
515		}
